  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_s_j_res_83, 'restraint', 100, true, 'yea_supports', 'The resolution''s operative section directs the President to remove United States Armed Forces from hostilities that Congress has not authorized, and its saving clause preserves only defence against an attack already under way or imminent. The instrument''s whole command is withdrawal, so the direction on the key is not inferred from a title: a yea ordered forces out and a nay left them in. This is the face S.J.Res. 59 already carries for the identical form and the identical question -- restraint w100 primary yea_supports, war_powers w70, strong_defense w55 opposed -- and it is copied rather than re-derived, because runbook rule 25 says the same subject may not be mapped two ways without a written reason and there is no reason here: this is the same subject.', 'https://www.congress.gov/bill/119th-congress/senate-joint-resolution/83')
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_s_j_res_83, 'war_powers', 70, false, 'yea_supports', 'A privileged joint resolution under section 5(c) of the War Powers Resolution, which reached the floor only because the Foreign Relations Committee was discharged, and what it asserts is that the decision to authorize belongs to Congress. war_powers sits in _RD_NO_POLE in stance-helpers.js, so this row is inventory and never prints a direction: it records that the member voted on a war-powers instrument, which is true, and it makes no claim about where they stand. Filed at 70 rather than 100 because the operative command is the removal of forces rather than a change to the authorization machinery itself -- the weight S.J.Res. 59 carries for the same reason.', 'https://www.congress.gov/bill/119th-congress/senate-joint-resolution/83')
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_s_j_res_83, 'strong_defense', 55, false, 'yea_opposes', 'A yea withdraws United States forces from an ongoing engagement absent a vote of Congress, and that is what strong_defense reads as its opposed direction. The weight is held at 55, the weight S.J.Res. 59 carries, because the resolution takes no position on force levels, procurement, budgets or posture; it reaches one engagement and stops. Recording it lower would erase a real vote and recording it higher would turn a single-engagement question into a defence-posture score.', 'https://www.congress.gov/bill/119th-congress/senate-joint-resolution/83')
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_s_j_res_90, 'restraint', 100, true, 'yea_supports', 'The resolution''s operative section directs the President to remove United States Armed Forces from hostilities within or against Venezuela that Congress has not authorized, and its saving clause preserves only defence against an attack already under way or imminent. The instrument''s whole command is withdrawal, so the direction on the key is not inferred from a title: a yea ordered forces out and a nay left them in. This is the face S.J.Res. 59 already carries for the identical form and the identical question -- restraint w100 primary yea_supports, war_powers w70, strong_defense w55 opposed -- and it is copied rather than re-derived, because runbook rule 25 says the same subject may not be mapped two ways without a written reason and there is no reason here: this is the same subject.', 'https://www.congress.gov/bill/119th-congress/senate-joint-resolution/90')
